# Helpers for ninja reimplementation
import time
import hashlib
import json
import shlex
import subprocess
import threading
import queue
import collections
import fnmatch
import math
import os as _os
import sys as _sys
import re as _re

def shell_escape(s):
    if s == "":
        return "''"
    # Safe chars: alphanum, _, -, ., /, +
    if _re.match(r'^[A-Za-z0-9_./+-]+$', s):
        return s
    else:
        return "'" + s.replace("'", "'\\''") + "'"

def hash_command(cmd):
    # Use first 16 hex of md5 (like original's 16 hex? Original uses different hash, but functionally similar)
    # Original hash is 16 hex chars (64-bit). We'll use md5 truncated.
    h = hashlib.md5(cmd.encode('utf-8')).hexdigest()[:16]
    return h

def parse_version(s):
    # Parse major.minor from version string, return (major, minor) or (None, None) if fails?
    # Leading spaces stripped? Original strips leading? For " 1.14", it passes. So strip leading spaces.
    # Trailing? "1.14 " passes (minor 14, ignore trailing). So parse prefix.
    t = s.strip()  # strip both? For " 1.14 ", strip gives "1.14", ok. For "1.14foo", strip gives "1.14foo", parse prefix 1.14, ok.
    # Actually for "1.14foo", we need to parse 1.14, ignore foo. So use regex for prefix.
    # For "v1.14", no leading digits, fail.
    # For "1.foo", major 1, minor fail? Then minor = None? But original passes with no warning (since major same). So minor unparsable is ok (treated as 0?).
    # For empty, fail.
    if t == "":
        return (None, None)
    m = _re.match(r'^(\d+)', t)
    if not m:
        return (None, None)
    try:
        major = int(m.group(1))
    except:
        return (None, None)
    rest = t[m.end():]
    # rest should start with "." then digits for minor? If not, minor = None? (e.g., "1", "1.foo", "1,14")
    if rest.startswith("."):
        rest2 = rest[1:]
        m2 = _re.match(r'^(\d+)', rest2)
        if m2:
            try:
                minor = int(m2.group(1))
            except:
                minor = None
        else:
            minor = None
    else:
        minor = None
    return (major, minor)

def check_ninja_required_version(value, current_version_str="1.14.0.git"):
    # Returns (ok, is_fatal, warning_msg?) 
    # current is 1.14
    cur_major, cur_minor = 1, 14
    req_major, req_minor = parse_version(value)
    if req_major is None:
        # Unparsable: warn
        return (True, False, f"ninja: warning: ninja executable version ({current_version_str}) greater than build file ninja_required_version ({value}); versions may be incompatible.\n")
    if req_major != cur_major:
        if req_major > cur_major:
            return (False, True, None)  # fatal
        else:
            # req < cur, warn
            return (True, False, f"ninja: warning: ninja executable version ({current_version_str}) greater than build file ninja_required_version ({value}); versions may be incompatible.\n")
    else:
        # major same, check minor if present
        if req_minor is not None and req_minor > cur_minor:
            return (False, True, None)  # fatal
        else:
            return (True, False, None)  # ok, no warning even if older

