import time as _time2, hashlib as _hashlib2, json as _json2, subprocess as _subprocess2, threading as _threading2, queue as _queue2, collections as _collections2, struct as _struct2, fnmatch as _fnmatch2
class NinjaFatal(Exception):
    pass
class NinjaErrorLoading(Exception):
    pass
class ParseError(Exception):
    def __init__(self, filename, lineno, msg, line_text=None, col=None):
        self.filename=filename;self.lineno=lineno;self.msg=msg;self.line_text=line_text;self.col=col
        super().__init__(msg)
    def format(self):
        base=f"ninja: error: {self.filename}:{self.lineno}: {self.msg}\n"
        if self.line_text is None:
            return base+"\n"
        lt=self.line_text
        if lt.endswith("\r\n"): lt=lt[:-2]
        elif lt.endswith("\n"): lt=lt[:-1]
        if self.col is None:
            return base+lt+"\n\n"
        return base+lt+"\n"+" "*self.col+"^ near here\n"

def shell_escape(s):
    if s=="": return "''"
    if re.match(r'^[A-Za-z0-9_./+-]+$',s): return s
    return "'"+s.replace("'","'\\''")+"'"

def hash_command(cmd):
    return hashlib.md5(cmd.encode('utf-8')).hexdigest()[:16]

def parse_version(s):
    t=s.strip()
    if t=="": return (None,None)
    m=re.match(r'^(\d+)',t)
    if not m: return (None,None)
    try: major=int(m.group(1))
    except: return (None,None)
    rest=t[m.end():]
    if rest.startswith("."):
        m2=re.match(r'^(\d+)',rest[1:])
        if m2:
            try: minor=int(m2.group(1))
            except: minor=None
        else: minor=None
    else: minor=None
    return (major,minor)

def check_version(value, cur_str="1.14.0.git"):
    cur_major,cur_minor=1,14
    req_major,req_minor=parse_version(value)
    if req_major is None:
        return (True,False,f"ninja: warning: ninja executable version ({cur_str}) greater than build file ninja_required_version ({value}); versions may be incompatible.\n")
    if req_major!=cur_major:
        if req_major>cur_major: return (False,True,None)
        else: return (True,False,f"ninja: warning: ninja executable version ({cur_str}) greater than build file ninja_required_version ({value}); versions may be incompatible.\n")
    else:
        if req_minor is not None and req_minor>cur_minor: return (False,True,None)
        else: return (True,False,None)

def expand_string(s, lookup, filename, lineno, line_text, col_offset, version_ok, is_path=False):
    res=[];i=0;n=len(s)
    while i<n:
        c=s[i]
        if c!='$':
            res.append(c);i+=1
        else:
            if i+1>=n:
                raise ParseError(filename,lineno,"bad $-escape (literal $ must be written as $$)",line_text,col_offset+i)
            nxt=s[i+1]
            if nxt=='$': res.append('$');i+=2
            elif nxt==' ': res.append(' ');i+=2
            elif nxt==':': res.append(':');i+=2
            elif nxt=='^':
                if not version_ok:
                    if is_path:
                        raise ParseError(filename,lineno,"using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14",None,None)
                    else:
                        try: eq_col=line_text.index("=") if line_text else col_offset+i
                        except: eq_col=col_offset+i
                        raise ParseError(filename,lineno,"using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14",line_text,eq_col)
                else: res.append('\n');i+=2
            elif nxt=='\n': i+=2
            elif nxt=='{':
                end=s.find('}',i+2)
                if end==-1: raise ParseError(filename,lineno,"bad $-escape (literal $ must be written as $$)",line_text,col_offset+i)
                var_name=s[i+2:end]
                if var_name=="" or not re.match(r'^[A-Za-z0-9_.-]+$',var_name):
                    raise ParseError(filename,lineno,"bad $-escape (literal $ must be written as $$)",line_text,col_offset+i)
                v=lookup(var_name)
                res.append("" if v is None else v);i=end+1
            elif re.match(r'[A-Za-z0-9_-]',nxt):
                m=re.match(r'^[A-Za-z0-9_-]+',s[i+1:])
                var_name=m.group(0)
                v=lookup(var_name)
                res.append("" if v is None else v);i+=1+len(var_name)
            else:
                raise ParseError(filename,lineno,"bad $-escape (literal $ must be written as $$)",line_text,col_offset+i)
    return ''.join(res)

def read_file_lines(path):
    try:
        with open(path,'rb') as f: data=f.read()
    except FileNotFoundError: return None
    except IsADirectoryError: return None
    try: text=data.decode('utf-8')
    except: text=data.decode('utf-8',errors='surrogateescape')
    return text.splitlines(keepends=True)

def join_continuations(physical_lines, filename):
    logical=[];i=0;n=len(physical_lines)
    while i<n:
        start_lineno=i+1
        parts=[]
        cur=physical_lines[i]
        while True:
            if cur.endswith("\r\n"): content=cur[:-2];newline="\r\n";has_nl=True
            elif cur.endswith("\n"): content=cur[:-1];newline="\n";has_nl=True
            else: content=cur;newline="";has_nl=False
            cnt=0
            for ch in reversed(content):
                if ch=='$': cnt+=1
                else: break
            is_cont=has_nl and (cnt%2==1)
            if is_cont:
                parts.append(content[:-1])
                i+=1
                if i>=n:
                    cur="";break
                else:
                    nxt=physical_lines[i]
                    stripped=nxt.lstrip(" \t")
                    cur=stripped
                    continue
            else:
                parts.append(content)
                logical_text="".join(parts)+newline
                logical.append((logical_text,start_lineno))
                i+=1
                break
    return logical

