def parse_depfile(path):
    try:
        with open(path,'r',errors='surrogateescape') as f: content=f.read()
    except: return None
    if ":" not in content: raise NinjaErrorLoading(f"ninja: error: {path}: expected ':' in depfile\n")
    content2=re.sub(r'\\\r?\n',' ',content)
    toks=[];cur="";i=0;n=len(content2)
    while i<n:
        ch=content2[i]
        if ch=='\\' and i+1<n:
            cur+=content2[i+1];i+=2;continue
        elif ch in (' ','\t','\n','\r'):
            if cur!="": toks.append(cur);cur=""
            while i<n and content2[i] in (' ','\t','\n','\r'): i+=1
            continue
        else: cur+=ch;i+=1;continue
    if cur!="": toks.append(cur)
    ci=-1;cp=-1
    for ii,t in enumerate(toks):
        p=t.find(":")
        if p!=-1: ci=ii;cp=p;break
    if ci==-1: raise NinjaErrorLoading(f"ninja: error: {path}: expected ':' in depfile\n")
    deps=[]
    aft=toks[ci][cp+1:]
    if aft!="": deps.append(aft)
    for t in toks[ci+1:]:
        if ":" in t:
            pp=t.find(":");a=t[pp+1:]
            if a!="": deps.append(a)
            continue
        else: deps.append(t)
    return deps

