def evaluate_edge(edge, dummy, state):
    bvars=edge.variables
    scope=getattr(edge,'scope',None)
    def fl(n):
        c=scope
        while c is not None:
            if n in c.vars: return c.vars[n]
            c=c.parent
        return None
    raw_in=" ".join(edge.inputs);raw_out=" ".join(edge.outputs)
    q_in=" ".join(shell_escape(p) for p in edge.inputs);q_out=" ".join(shell_escape(p) for p in edge.outputs)
    raw_nl="\n".join(edge.inputs);q_nl="\n".join(shell_escape(p) for p in edge.inputs)
    def mk(q):
        def lk(n):
            if n=="in": return q_in if q else raw_in
            if n=="in_newline": return q_nl if q else raw_nl
            if n=="out": return q_out if q else raw_out
            if n in bvars: return bvars[n]
            return fl(n)
        return lk
    res={}
    if edge.rule is None: return res
    for k,raw in edge.rule.vars.items():
        q=(k in ("command","description"))
        try: res[k]=expand_string(raw,mk(q),edge.filename,edge.lineno,None,0,True,False)
        except: res[k]=raw
    for k,v in bvars.items(): res[k]=v
    return res
