                    if e.rule_name==arg:
                        for o in e.outputs: res.append(o)
                res.sort()
                for r in res: sys.stdout.write(r+"\n")
                return 0
        elif mode=="all":
            for e in state.edges:
                for o in e.outputs: sys.stdout.write(f"{o}: {e.rule_name}\n")
                for o in e.implicit_outputs: sys.stdout.write(f"{o}: {e.rule_name}\n")
